package $PACKAGE_NAME.focusflow

import android.app.PendingIntent
import android.appwidget.AppWidgetManager
import android.appwidget.AppWidgetProvider
import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.view.View
import android.widget.RemoteViews
import org.json.JSONArray
import org.json.JSONObject

internal abstract class FocusFlowBaseWidgetProvider : AppWidgetProvider() {
  abstract fun layoutResource(): Int
  abstract fun bind(views: RemoteViews, state: JSONObject)
  open fun bindAction(context: Context, id: Int, views: RemoteViews, state: JSONObject) = Unit
  override fun onUpdate(context: Context, manager: AppWidgetManager, ids: IntArray) { ids.forEach { updateWidget(context, manager, it) } }
  override fun onReceive(context: Context, intent: Intent) { if (intent.action == ACTION_COMPLETE) { val targetId = intent.getStringExtra(EXTRA_TARGET_ID).orEmpty(); val kind = intent.getStringExtra(EXTRA_KIND).orEmpty(); if (targetId.isNotBlank() && (kind == "todo" || kind == "habit")) { complete(context, targetId, kind); FocusFlowWidgetProvider.refreshAll(context) }; return }; super.onReceive(context, intent) }
  fun updateWidget(context: Context, manager: AppWidgetManager, id: Int) { val current = state(context); val views = RemoteViews(context.packageName, layoutResource()); bind(views, current); bindAction(context, id, views, current); views.setOnClickPendingIntent(R.id.focus_flow_widget_root, launchIntent(context, id)); manager.updateAppWidget(id, views) }
  protected fun state(context: Context): JSONObject { val saved = context.getSharedPreferences(FocusGateModule.GATE_PREFS, Context.MODE_PRIVATE).getString(FocusGateModule.GATE_STATE, null); return try { JSONObject(saved ?: "{}") } catch (_: Exception) { JSONObject() } }
  protected fun launchIntent(context: Context, id: Int): PendingIntent { val launch = context.packageManager.getLaunchIntentForPackage(context.packageName)?.apply { addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP) }; return PendingIntent.getActivity(context, id, launch, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE) }
  protected fun en(state: JSONObject) = state.optString("language", "ja") == "en"
  protected fun active(state: JSONObject) = state.optBoolean("active", false)
  protected fun completeIntent(context: Context, id: Int, targetId: String, kind: String): PendingIntent = PendingIntent.getBroadcast(context, (id.toString() + targetId + kind).hashCode(), Intent(context, javaClass).apply { action = ACTION_COMPLETE; putExtra(EXTRA_TARGET_ID, targetId); putExtra(EXTRA_KIND, kind) }, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
  private fun complete(context: Context, targetId: String, kind: String) { val preferences = context.getSharedPreferences(FocusGateModule.GATE_PREFS, Context.MODE_PRIVATE); val state = state(context); val expectedId = if (kind == "todo") state.optString("nextRequiredId") else state.optString("nextHabitId"); if (targetId != expectedId) return; val queued = try { JSONArray(preferences.getString(FocusGateModule.WIDGET_COMPLETIONS, "[]") ?: "[]") } catch (_: Exception) { JSONArray() }; var alreadyQueued = false; for (index in 0 until queued.length()) { val item = queued.optJSONObject(index); if (item?.optString("id") == targetId && item.optString("kind") == kind) alreadyQueued = true }; if (alreadyQueued) return; queued.put(JSONObject().put("id", targetId).put("kind", kind)); state.put("pendingCount", (state.optInt("pendingCount") - 1).coerceAtLeast(0)); val queueKey = if (kind == "todo") "todoQueue" else "habitQueue"; val queue = state.optJSONArray(queueKey) ?: JSONArray(); val remainingQueue = JSONArray(); for (index in 0 until queue.length()) { val item = queue.optJSONObject(index) ?: continue; if (item.optString("id") != targetId) remainingQueue.put(item) }; state.put(queueKey, remainingQueue); val next = remainingQueue.optJSONObject(0); if (kind == "todo") { state.put("pendingTodos", (state.optInt("pendingTodos") - 1).coerceAtLeast(0)); state.put("completedTodoTotal", state.optInt("completedTodoTotal") + 1); state.put("nextTodoId", next?.optString("id") ?: ""); state.put("nextTodoTitle", next?.optString("title") ?: "") } else { state.put("pendingHabits", (state.optInt("pendingHabits") - 1).coerceAtLeast(0)); state.put("completedHabitTotal", state.optInt("completedHabitTotal") + 1); state.put("nextHabitId", next?.optString("id") ?: ""); state.put("nextHabitTitle", next?.optString("title") ?: "") }; val nextTodoId = state.optString("nextTodoId"); val nextHabitId = state.optString("nextHabitId"); if (nextTodoId.isNotBlank()) { state.put("nextRequiredId", nextTodoId); state.put("nextRequiredTitle", state.optString("nextTodoTitle")); state.put("nextRequiredKind", "todo") } else if (nextHabitId.isNotBlank()) { state.put("nextRequiredId", nextHabitId); state.put("nextRequiredTitle", state.optString("nextHabitTitle")); state.put("nextRequiredKind", "habit") } else { state.put("nextRequiredId", ""); state.put("nextRequiredTitle", ""); state.put("nextRequiredKind", "") }; val rules = state.optJSONArray("rules") ?: JSONArray(); for (index in 0 until rules.length()) { val rule = rules.optJSONObject(index) ?: continue; val ids = if (kind == "todo") rule.optJSONArray("pendingTodoIds") else rule.optJSONArray("pendingHabitIds"); var found = false; if (ids != null) for (idIndex in 0 until ids.length()) if (ids.optString(idIndex) == targetId) found = true; if (found) { val remaining = JSONArray(); if (ids != null) for (idIndex in 0 until ids.length()) { val value = ids.optString(idIndex); if (value != targetId) remaining.put(value) }; if (kind == "todo") { rule.put("pendingTodoIds", remaining); rule.put("pendingTodos", (rule.optInt("pendingTodos") - 1).coerceAtLeast(0)) } else { rule.put("pendingHabitIds", remaining); rule.put("pendingHabits", (rule.optInt("pendingHabits") - 1).coerceAtLeast(0)) }; rule.put("pendingCount", (rule.optInt("pendingCount") - 1).coerceAtLeast(0)) } }; preferences.edit().putString(FocusGateModule.GATE_STATE, state.toString()).putString(FocusGateModule.WIDGET_COMPLETIONS, queued.toString()).putLong(FocusGateModule.GATE_STATE_UPDATED_AT, System.currentTimeMillis()).apply() }
  companion object { const val ACTION_COMPLETE = "focusflow.widget.COMPLETE"; const val EXTRA_TARGET_ID = "targetId"; const val EXTRA_KIND = "kind" }
}

class FocusFlowWidgetProvider : FocusFlowBaseWidgetProvider() {
  override fun layoutResource() = R.layout.focus_flow_widget
  override fun bind(views: RemoteViews, state: JSONObject) { val pending = state.optInt("pendingCount", 0); val english = en(state); views.setTextViewText(R.id.focus_flow_widget_count, if (pending == 0) if (english) "Done" else "完了" else if (english) "$pending left" else "${pending}件"); views.setTextViewText(R.id.focus_flow_widget_status, if (!active(state)) if (english) "App limits are off" else "アプリ制限はオフ" else if (pending == 0) if (english) "Today’s must-dos are complete" else "今日の必須項目を完了しました" else if (english) "Finish must-dos to unlock apps" else "必須項目を終えてアプリを解除") }
  companion object { private val providers = listOf(FocusFlowWidgetProvider::class.java, FocusFlowProgressWidgetProvider::class.java, FocusFlowNextWidgetProvider::class.java, FocusFlowHabitWidgetProvider::class.java, FocusFlowRoutineWidgetProvider::class.java); fun refreshAll(context: Context) { val manager = AppWidgetManager.getInstance(context); providers.forEach { clazz -> val provider = clazz.getDeclaredConstructor().newInstance(); manager.getAppWidgetIds(ComponentName(context, clazz)).forEach { id -> provider.updateWidget(context, manager, id) } } } }
}

class FocusFlowProgressWidgetProvider : FocusFlowBaseWidgetProvider() {
  override fun layoutResource() = R.layout.focus_flow_widget_progress
  override fun bind(views: RemoteViews, state: JSONObject) { val english = en(state); val total = state.optInt("requiredTodoTotal", 0) + state.optInt("requiredHabitTotal", 0); val done = state.optInt("completedTodoTotal", 0) + state.optInt("completedHabitTotal", 0); views.setTextViewText(R.id.focus_flow_widget_title, if (english) "UNLOCK PROGRESS" else "解除の進捗"); views.setTextViewText(R.id.focus_flow_widget_main, if (total == 0) if (english) "Add a must-do" else "必須項目を追加" else "$done / $total"); views.setTextViewText(R.id.focus_flow_widget_detail, if (english) "Tasks ${state.optInt("completedTodoTotal", 0)}/${state.optInt("requiredTodoTotal", 0)} · Habits ${state.optInt("completedHabitTotal", 0)}/${state.optInt("requiredHabitTotal", 0)}" else "Todo ${state.optInt("completedTodoTotal", 0)}/${state.optInt("requiredTodoTotal", 0)} ・ 習慣 ${state.optInt("completedHabitTotal", 0)}/${state.optInt("requiredHabitTotal", 0)}") }
}

class FocusFlowNextWidgetProvider : FocusFlowBaseWidgetProvider() {
  override fun layoutResource() = R.layout.focus_flow_widget_next
  override fun bind(views: RemoteViews, state: JSONObject) { val english = en(state); val title = state.optString("nextRequiredTitle", ""); val kind = state.optString("nextRequiredKind", ""); views.setTextViewText(R.id.focus_flow_widget_title, if (english) "NEXT MUST-DO" else "次の必須項目"); views.setTextViewText(R.id.focus_flow_widget_main, if (title.isBlank()) if (english) "You’re all set" else "すべて完了です" else title); views.setTextViewText(R.id.focus_flow_widget_detail, if (title.isBlank()) if (english) "Open Focus Flow to plan tomorrow" else "Focus Flowで明日の予定を整えましょう" else if (kind == "habit") if (english) "Record today’s habit" else "今日の習慣を記録" else if (english) "Complete this task to unlock apps" else "完了するとアプリを解除できます"); views.setViewVisibility(R.id.focus_flow_widget_action, if (title.isBlank()) View.GONE else View.VISIBLE); views.setTextViewText(R.id.focus_flow_widget_action, if (english) "Mark complete" else "完了にする") }
  override fun bindAction(context: Context, id: Int, views: RemoteViews, state: JSONObject) { val targetId = state.optString("nextRequiredId"); val kind = state.optString("nextRequiredKind"); if (targetId.isNotBlank() && (kind == "todo" || kind == "habit")) views.setOnClickPendingIntent(R.id.focus_flow_widget_action, completeIntent(context, id, targetId, kind)) }
}

class FocusFlowHabitWidgetProvider : FocusFlowBaseWidgetProvider() {
  override fun layoutResource() = R.layout.focus_flow_widget_habit
  override fun bind(views: RemoteViews, state: JSONObject) { val english = en(state); val total = state.optInt("requiredHabitTotal", 0); val done = state.optInt("completedHabitTotal", 0); val targetId = state.optString("nextHabitId"); views.setTextViewText(R.id.focus_flow_widget_title, if (english) "HABIT PULSE" else "習慣の記録"); views.setTextViewText(R.id.focus_flow_widget_main, if (total == 0) if (english) "No must-do habits" else "必須習慣はありません" else if (english) "$done of $total complete" else "$done / $total を完了"); views.setTextViewText(R.id.focus_flow_widget_detail, if (total == 0) if (english) "Add one when a routine matters" else "習慣を必須にするとここに表示" else if (done == total) if (english) "Today’s required habits are done" else "今日の必須習慣は完了しました" else if (english) "Tap to record your progress" else "タップして進捗を記録"); views.setViewVisibility(R.id.focus_flow_widget_action, if (targetId.isBlank()) View.GONE else View.VISIBLE); views.setTextViewText(R.id.focus_flow_widget_action, if (english) "Complete habit" else "習慣を完了") }
  override fun bindAction(context: Context, id: Int, views: RemoteViews, state: JSONObject) { val targetId = state.optString("nextHabitId"); if (targetId.isNotBlank()) views.setOnClickPendingIntent(R.id.focus_flow_widget_action, completeIntent(context, id, targetId, "habit")) }
}

class FocusFlowRoutineWidgetProvider : FocusFlowBaseWidgetProvider() {
  override fun layoutResource() = R.layout.focus_flow_widget_routine
  override fun bind(views: RemoteViews, state: JSONObject) { val english = en(state); val label = state.optString("routineLabel", ""); val routineOn = state.optBoolean("routineActive", false); views.setTextViewText(R.id.focus_flow_widget_title, if (english) "ROUTINE STATUS" else "日課の状態"); views.setTextViewText(R.id.focus_flow_widget_main, if (!active(state)) if (english) "App limits are off" else "アプリ制限はオフ" else if (routineOn) if (label.isBlank()) if (english) "Routine active" else "日課を適用中" else label else if (english) "No routine active" else "日課の時間外です"); views.setTextViewText(R.id.focus_flow_widget_detail, if (!active(state)) if (english) "Turn on App limits in Settings" else "設定からアプリ制限をオンにできます" else if (routineOn) if (english) "Tap to review today’s unlock progress" else "タップして今日の解除進捗を確認" else if (english) "Your next routine will resume automatically" else "次の日課の時間になると自動で再開") }
}
